import sys

def find_difference_count(a, b, l, r):
    first = b if b < a else a - 1
    last = a - 1
    sb = []

    for i in range(a):
        sb.append(chr(ord('a') + i))
    ch = sb[last] if l < a else sb[first]

    for _ in range(b):
        sb.append(ch)

    used_letters = [False] * 30
    for i in range(a):
        used_letters[ord(sb[-i - 1]) - ord('a')] = True

    ptr = 0
    for _ in range(a):
        while used_letters[ptr]:
            ptr += 1
        sb.append(chr(ord('a') + ptr))
        used_letters[ptr] = True

    ch = sb[min(b, a - 1) + a + b]
    for _ in range(b):
        sb.append(ch)

    for i in range(a + b):
        sb.append(sb[i])

    return count_distinct_letters(''.join(sb), l, r)

def count_distinct_letters(s, l, r):
    used = [False] * 30
    for i in range(l, r + 1):
        used[ord(s[i]) - ord('a')] = True
    return sum(used)

def main():
    data = sys.stdin.read().strip().split()
    a = int(data[0])
    b = int(data[1])
    l = int(data[2]) - 1
    r = int(data[3]) - 1
    total_length = a + b
    diff = r - l
    if diff >= 2 * total_length:
        result = max(a + 1, 2 * a - b)
    else:
        r -= total_length * (l // total_length)
        l %= total_length
        result = find_difference_count(a, b, l, r)
    print(result)

